const isObj = (v: unknown): v is Record<string, unknown> => typeof v === "object" && v !== null && !Array.isArray(v);

/** Per-kind checks of input_spec and expected_spec (spec 8.3). Returns [field, message] problems. */
export function validateTestCaseSpecs(kind: TaskKind, input: unknown, expected: unknown, comparison?: string): [("inputSpec" | "expectedSpec"), string][] {
  const out: [("inputSpec" | "expectedSpec"), string][] = [];
  if (!isObj(input)) return [["inputSpec", "Must be a JSON object."]];
  if (!isObj(expected)) return [["expectedSpec", "Must be a JSON object."]];
  switch (kind) {
    case "FUNCTION":
      if (typeof input.function !== "string" || !input.function) out.push(["inputSpec", 'Needs a "function" name, e.g. {"function":"add","args":[2,3]}.']);
      if (!Array.isArray(input.args)) out.push(["inputSpec", 'Needs an "args" array.']);
      if (!("returns" in expected)) out.push(["expectedSpec", 'Needs a "returns" value, e.g. {"returns":5}.']);
      break;
    case "STDIO":
      if (input.stdin !== undefined && typeof input.stdin !== "string") out.push(["inputSpec", '"stdin" must be text.']);
      if (typeof expected.stdout !== "string") out.push(["expectedSpec", 'Needs a "stdout" text value.']);
      break;
    case "HTTP":
      if (!["GET", "POST", "PUT", "PATCH", "DELETE"].includes(String(input.method))) out.push(["inputSpec", '"method" must be GET, POST, PUT, PATCH or DELETE.']);
      if (typeof input.path !== "string" || !input.path.startsWith("/")) out.push(["inputSpec", '"path" must start with /.']);
      if (typeof input.startCommand !== "string" || !input.startCommand) out.push(["inputSpec", 'Needs a "startCommand", e.g. "node src/server.js".']);
      if (!Number.isInteger(input.port) || (input.port as number) < 1 || (input.port as number) > 65535) out.push(["inputSpec", '"port" must be 1 to 65535.']);
      if (!Number.isInteger(expected.status) || (expected.status as number) < 100 || (expected.status as number) > 599) out.push(["expectedSpec", 'Needs a "status" code, e.g. 200.']);
      break;
    case "BROWSER":
      if (Object.keys(input).length === 0) out.push(["inputSpec", "Describe the page interaction."]);
      if (Object.keys(expected).length === 0) out.push(["expectedSpec", "Describe the expected result."]);
      break;
    case "GIT":
      if (typeof input.check !== "string" || !input.check) out.push(["inputSpec", 'Needs a "check", e.g. {"check":"repo_state"}.']);
      if (Object.keys(expected).length === 0) out.push(["expectedSpec", "Describe the expected repository state."]);
      break;
  }
  if (comparison === "float_tolerance" && typeof expected.epsilon !== "number") out.push(["expectedSpec", 'float_tolerance needs a numeric "epsilon".']);
  return out;
}

